/* Mabat application. Runs directly from index.html and from static hosting. */
'use strict';
const C=MabatCore,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),safeURL=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const link=(url,label)=>safeURL(url)?`<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label||url)} ↗</a>`:esc(label||url);
const opt=(id,label,selected='')=>`<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(['מוצע לדיון','סביר','מבוסס'].includes(label)?T(label):label)}</option>`;
const btn=(action,label,cls='',extra='')=>`<button data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
let P=C.fresh(),assets={},undoStack=[],db=null,saveTimer,saveQueue=Promise.resolve(),toastTimer,saveInFlight=0;
let ui={tab:'collection',imageId:null,selected:null,tool:'select',zoom:100,model:'edit',modelGraph:false,analysis:'heat',analysisLayer:'all',metric:'occurrences',work:'',author:'',descendants:false,pack:'starter',packSelection:null};
let polygon=[],draft=null,importMode='open',importedPack=null;
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',6000);}
function openDialog(html,setup){$('dialogBody').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();setup?.();bindBi();decorateHelp($('dialogBody'));}
function closeDialog(){$('dialog').close();}
function checkpoint(action){undoStack.push({p:C.clone(P),a:{...assets}});if(undoStack.length>18)undoStack.shift();P.history.push({id:C.uid(),time:C.now(),author:P.author,action});if(P.history.length>250)P.history.shift();}
function mutate(action,fn){checkpoint(action);try{fn();P.updated=C.now();const errors=C.validate(P);if(errors.length)throw Error(errors.join('\n'));}catch(e){const previous=undoStack.pop();P=previous.p;assets=previous.a;toast(e.message);return false;}scheduleSave();render();return true;}
function scheduleSave(){clearTimeout(saveTimer);$('saveStatus').textContent=T("שינויים ממתינים לשמירה…");saveTimer=setTimeout(persist,350);}
async function persist(){clearTimeout(saveTimer);saveTimer=null;if(!db){$('saveStatus').textContent=T("שמירה בדפדפן לא זמינה · הורידו פרויקט");$('saveStatus').className='status-error';return;}const payload={project:C.clone(P),assets:{...assets}};saveQueue=saveQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{saveInFlight++;const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(payload,'active');tx.oncomplete=()=>{saveInFlight--;if(!saveTimer){$('saveStatus').textContent='נשמר בדפדפן · '+new Date().toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'});$('saveStatus').className='';}resolve();};tx.onerror=()=>{saveInFlight--;reject(tx.error);};tx.onabort=()=>{saveInFlight=Math.max(0,saveInFlight-1);reject(tx.error||Error('Storage transaction aborted'));};})).catch(e=>{$('saveStatus').textContent=T("השמירה נכשלה · הורידו פרויקט");$('saveStatus').className='status-error';toast('לא ניתן לשמור בדפדפן: '+e.message+'. הורידו חבילת פרויקט.');});return saveQueue;}
async function init(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('mabat-sequence-studio-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});const stored=await new Promise((resolve,reject)=>{const req=db.transaction('projects').objectStore('projects').get('active');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(stored){const errors=C.validate(stored.project,stored.assets);if(errors.length)throw Error('העותק השמור אינו תקין: '+errors.join('; '));P=stored.project;assets=stored.assets;}$('saveStatus').textContent=T("שמירה מקומית פעילה");}catch(e){db=null;$('saveStatus').textContent=T("שמירה בדפדפן לא זמינה · הורידו פרויקט");toast(e.message);}render();}
function getImage(){return P.images.find(x=>x.id===ui.imageId)||P.images[0];}
function groupOf(c){return P.groups.find(g=>g.id===c?.groupId);}
function conceptLabel(id){return L(P.concepts.find(c=>c.id===id))||id;}
function annotationLabel(a){const im=P.images.find(x=>x.id===a.imageId);return `${L(im,'title')||im?.name||T('עמוד')} · ${L(a)||a.conceptIds.map(conceptLabel).join(', ')||T('אזור')} [${P.annotations.indexOf(a)+1}]`;}
function nodeInfo(id){const a=P.annotations.find(x=>x.id===id);if(a)return {label:annotationLabel(a),type:'annotation',color:'#1d6658'};const c=P.claims.find(x=>x.id===id);if(c)return {label:L(c,'text')||c.conceptIds.map(conceptLabel).join(', '),type:'claim',color:'#79619b'};const im=P.images.find(x=>x.id===id);if(im)return {label:L(im,'title')||im.name,type:'image',color:'#b68a42'};const con=P.concepts.find(x=>x.id===id);if(con)return {label:L(con),type:'concept',color:groupOf(con)?.color||'#467d9a'};return {label:id,type:'unknown',color:'#888'};}
function render(){for(const r of P.relationTypes){if(!r.labels&&r.kind!=='custom'&&MabatI18n.dict[r.label])r.labels={he:r.label,en:MabatI18n.dict[r.label]};}document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===ui.tab));$('projectName').value=P.name;$('author').value=P.author;$('summary').textContent=`${P.images.length} ${T("תמונות · ")}${P.annotations.length} ${T("סימונים · ")}${P.claims.length} ${T("טענות")}`;$('undo').disabled=!undoStack.length;const renderers={collection:renderCollection,model:renderModel,annotate:renderAnnotate,analysis:renderAnalysis,help:renderHelp};P.catalogs??=[];P.sourceConnections??=[];$('main').innerHTML=renderers[ui.tab]();bindView();enhanceView();}
function heading(k,title,sub,actions=''){return `<div class="sectionhead"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="toolbar">${actions}</div></div>`;}
function renderCollection(){return heading(T("האוסף והרצף"),T("מעמוד בודד לרצף שאפשר לחקור"),T("הוסיפו תמונות, הגדירו יצירות וסדרו את הרצף. סדר העמודים נשמר בנפרד ממספרי העמודים המקוריים."),btn('add-images',T("＋ הוספת תמונות"),'primary')+btn('demo',T("טעינת דוגמה לימודית")))+
(!P.images.length?`<div class="empty"><div class="metric">▧</div><h2>${T("מתחילים מן החומר")}</h2><p>${T("אפשר להעלות כמה תמונות יחד, להגדיר את המושגים בזמן העבודה, ולחזור מאוחר יותר לכל עמוד. שום תמונה אינה נשלחת לשרת.")}</p>${btn('add-images',T("בחירת תמונות"),'primary')} ${btn('go-model',T("בניית אוצר מילים"))}</div>`:
`<div class="notice">${T("גררו כרטיס כדי לשנות את הסדר, או השתמשו בכפתורי ההזזה. הכפתור ״תיוג״ פותח את העמוד. בדיקה של קבוצות התגיות נעשית באזור התיוג.")}</div><div class="cards">${P.images.map((im,i)=>`<article class="imagecard" draggable="true" data-image="${im.id}"><span class="number">${i+1}</span><div class="thumb" data-action="annotate-image" data-id="${im.id}"><img src="${esc(assets[im.id])}" alt="${esc(L(im,'title')||L(im,'name'))}"></div><div class="body">${imageMeta(im,'title',T('כותרת'))}<div class="smallfields">${imageMeta(im,'work',T('יצירה / קבוצה'))}<label>${T("מספר עמוד מקור")}<input data-im-field="page" data-id="${im.id}" value="${esc(im.page)}"></label></div><small class="muted">${esc(L(im,'name'))} · ${P.annotations.filter(a=>a.imageId===im.id).length} ${T("סימונים")}</small><div class="toolbar" style="margin-top:10px">${btn('annotate-image',T("תיוג"),'primary',`data-id="${im.id}"`)}${btn('move-prev','→','',`data-id="${im.id}" aria-label="${T("מוקדם יותר ברצף")}" ${i===0?'disabled':''}`)}${btn('move-next','←','',`data-id="${im.id}" aria-label="${T("מאוחר יותר ברצף")}" ${i===P.images.length-1?'disabled':''}`)}${btn('delete-image',T("מחיקה"),'danger',`data-id="${im.id}"`)}</div></div></article>`).join('')}</div>`);}
function renderModel(){let html=heading(T("מושגים וקשרים"),T("בונים שפה משותפת"),T("קבוצות מארגנות ערכים; היררכיה מגדירה סוגים ותתי־סוגים; קשרים מחברים מושגים או מופעים. אפשר לשנות את המודל גם במהלך התיוג."),btn('new-group',T("＋ קבוצה"),'primary')+btn('new-concept',T("＋ מושג"))+btn('new-relation-type',T("＋ סוג קשר")));
html+=`<div class="tabs">${[['edit',T("המודל של הפרויקט")],['library',T("מקורות וערכות")],['relations',T("סוגי קשרים")]].map(([id,l])=>btn('model-tab',l,ui.model===id?'active':'',`data-id="${id}"`)).join('')}<span style="flex:1"></span>${btn('import-vocab',T("ייבוא אוצר מילים"))}${btn('export-vocab',T("ייצוא אוצר מילים"))}</div>`;
if(ui.model==='library')return html+renderLibrary();
if(ui.model==='relations')return html+`<div class="panel"><p>${T("סוגי קשרים זמינים גם בין עמודים. אפשר להגביל את סוג פריט המקור והיעד כדי למנוע חיבורים לא מתאימים.")}</p>${P.relationTypes.map(r=>`<div class="termrow"><span class="grow"><b>${esc(L(r,'label'))}</b> <small class="muted">${esc(relationKind(r.kind))} · ${esc(endpointType(r.from))} ← ${esc(endpointType(r.to))}</small>${r.uri?`<br>${link(r.uri,T("מזהה מקור"))}`:''}</span>${btn('edit-relation-type',T("עריכה"),'',`data-id="${r.id}"`)}${btn('delete-relation-type',T("מחיקה"),'danger',`data-id="${r.id}"`)}</div>`).join('')}</div>`;
const edges=[...P.concepts.flatMap(c=>c.parents.map(p=>({source:c.id,target:p,label:T("סוג של")}))),...P.conceptLinks.map(r=>({...r,label:P.relationTypes.find(t=>t.id===r.typeId)?.label}))];
html+=`<div class="tabs">${btn('model-list',T("רשימה ועץ"),!ui.modelGraph?'active':'')}${btn('model-graph',T("רשת מושגים"),ui.modelGraph?'active':'')}${btn('concept-link',T("＋ קשר בין מושגים"))}</div>`;
const linkRows=P.conceptLinks.length?`<div class="panel"><h3>${T("קשרים בין מושגים")}</h3>${P.conceptLinks.map(r=>`<div class="termrow"><span class="grow">${esc(conceptLabel(r.source))} ← ${esc(L(P.relationTypes.find(t=>t.id===r.typeId),'label'))} ← ${esc(conceptLabel(r.target))}</span>${btn('delete-concept-link',T("מחיקה"),'danger',`data-id="${r.id}"`)}</div>`).join('')}</div>`:'';if(ui.modelGraph)return html+`<div class="panel"><p class="small muted">${T("חץ מצביע ממושג אל מושג האב שלו. צמתים ללא קשר נשארים עצמאיים. לחצו על צומת להצגת פרטיו. ")}${P.concepts.length>160?T("מוצגים 160 המושגים הראשונים בלבד."):''}</p>${graph(P.concepts.map(c=>({id:c.id,label:L(c),color:groupOf(c)?.color})),edges,'concept')}</div>`+linkRows;
if(!P.groups.length)return html+`<div class="empty"><h2>${T("מה נרצה לשמור?")}</h2><p>${T("צרו קבוצה כמו ״צבעים״ או ״סוגי אובייקטים״ והוסיפו לה ערכים. אפשר גם לבחור ערכת פתיחה ממקורות וערכות.")}</p>${btn('new-group',T("יצירת קבוצה"),'primary')} ${btn('model-library',T("בחירת ערכה"))}</div>`;
return html+`<div class="grid two">${P.groups.map(g=>`<div class="panel"><div class="sectionhead"><div><h2><span class="dot" style="background:${esc(g.color)}"></span> ${esc(L(g,'label'))}</h2><span class="badge ${g.layer==='meaning'?'meaning':''}">${T(C.layers[g.layer])}</span><span class="small muted">${g.selection==='single'?T("ערך יחיד לכל סימון / טענה"):T("בחירה מרובה")}</span></div>${btn('edit-group',T("עריכה"),'',`data-id="${g.id}"`)}</div>${conceptTree(g.id)}<div class="toolbar" style="margin-top:15px">${btn('new-concept',T("＋ ערך בקבוצה"),'',`data-group="${g.id}"`)}${btn('delete-group',T("מחיקת קבוצה"),'danger',`data-id="${g.id}"`)}</div></div>`).join('')}</div>`;}
function conceptTree(groupId){const list=P.concepts.filter(c=>c.groupId===groupId),seen=new Set();function row(c,depth){if(seen.has(c.id))return '';seen.add(c.id);return `<div class="termrow" style="margin-inline-start:${Math.min(depth,5)*18}px"><span class="grow"><b>${esc(L(c,'label'))}</b>${c.parents.length>1?H("<span class=\"badge\">כמה הורים</span>"):''}${c.definition?`<br><small class="muted">${esc(L(c,'definition'))}</small>`:''}${c.uri?`<br><small>${link(c.uri,T("מקור"))}</small>`:''}</span>${btn('edit-concept',T("עריכה"),'',`data-id="${c.id}"`)}</div>`+list.filter(x=>x.parents.includes(c.id)).map(x=>row(x,depth+1)).join('');}return list.filter(c=>!c.parents.some(id=>list.some(x=>x.id===id))).map(c=>row(c,0)).join('')+list.filter(c=>!seen.has(c.id)).map(c=>row(c,0)).join('');}
function relationKind(k){return {spatial:T("מרחבי בדף"),temporal:T("זמן הסיפור"),reading:T("סדר קריאה"),interpretive:T("פרשני"),identity:T("זהות"),evidence:T("ראיה"),custom:T("מותאם"),conceptual:T("מושגי")}[k]||k;}
function endpointType(k){return {any:T("כל פריט"),annotation:T("סימון"),claim:T("טענה"),image:T("עמוד"),concept:T("מושג")}[k]||k;}
function allPacks(){return [...MabatPacks,...(P.catalogs||[]),...(importedPack&&!(P.catalogs||[]).some(p=>p.id===importedPack.id)?[importedPack]:[])];}
function currentPack(){return allPacks().find(p=>p.id===ui.pack)||MabatPacks[0];}
function catalogTerms(pack){const query=(ui.catalogQuery||'').toLocaleLowerCase();return pack.terms.filter(t=>(!ui.catalogKind||(t.kind||'concept')===ui.catalogKind)&&(!query||[t.label,t.id,t.uri,...Object.values(t.labels||{}),...Object.values(t.definitions||{}),...Object.values(t.altLabels||{}).flat()].join(' ').toLocaleLowerCase().includes(query)));}
function renderLibrary(){const pack=currentPack(),selection=new Set(ui.packSelection||[]),terms=catalogTerms(pack),page=ui.catalogPage||0,visible=terms.slice(page*70,(page+1)*70),by=new Map(pack.terms.map(t=>[t.id,t])),byUri=new Map(pack.terms.map(t=>[t.uri,t]));let edges=[];
for(const t of terms.slice(0,160)){for(const parent of t.parents||[])if(by.has(parent))edges.push({source:t.id,target:parent,label:B('סוג / רחב יותר','Type / broader')});for(const r of t.related||[])edges.push({source:t.id,target:r,label:B('קשור','Related')});if(t.kind==='relation'&&t.domain?.length===1&&t.range?.length===1&&!t.domain[0].startsWith('_:')&&!t.range[0].startsWith('_:')){const domain=byUri.get(t.domain[0]),range=byUri.get(t.range[0]);if(domain&&range)edges.push({source:domain.id,target:range.id,label:L(t)});}}
return `<div class="catalog-layout"><aside class="panel"><h3>${B('אוצרות מילים זמינים','Available vocabularies')}</h3>${allPacks().map(p=>`<p>${btn('choose-pack',esc(L(p,'name')||L(p)),p.id===pack.id?'primary':'',`data-id="${esc(p.id)}"`)}<small class="muted">${p.terms.length} ${B('מונחים ויחסים','terms and relations')}</small></p>`).join('')}${btn('connections',B('＋ חיבור למקור נוסף','＋ Connect another source'),'primary')}${btn('import-vocab',B('ייבוא מקובץ','Import from file'))}<p class="small muted">${B('בחירת מקור אינה מוסיפה ערכים לפרויקט. עיינו, חפשו ובחרו מה לאמץ.','Selecting a source does not add terms to the project. Browse, search and choose what to adopt.')}</p></aside><section><div class="panel"><div class="sectionhead"><div><h2>${esc(L(pack,'name')||L(pack))} ${infoButton('ontologies')}</h2><p class="small">${esc(pack.notes?.[MabatI18n.lang]||H(L(pack,'note')||''))}</p></div>${btn('connections',B('מקורות וחיבורים','Sources and connections'))}</div><div class="mini-metrics"><span>${pack.terms.filter(t=>t.kind!=='relation').length} ${B('מושגים','concepts')}</span><span>${pack.terms.filter(t=>t.kind==='relation').length} ${B('סוגי קשרים','relation types')}</span><span>${selection.size} ${B('נבחרו','selected')}</span>${pack.report?.languages?.length?`<span>${esc(pack.report.languages.join(' · '))}</span>`:''}</div><p class="small source-details">${pack.source?link(pack.source,B('מקור','Source')):''} · ${esc(pack.license||B('הרישיון לא סופק; בדקו במקור.','License not provided; check the source.'))}${pack.fetchedAt?' · '+new Date(pack.fetchedAt).toLocaleString(MabatI18n.lang==='he'?'he-IL':'en-GB'):''}</p>${pack.report?.triples?`<details class="notice"><summary>${B('דוח ייבוא','Import report')}: ${pack.report.triples} ${B('שלשות נקראו','triples read')}</summary><p>${pack.report.mapped} ${B('מופו לשדות נתמכים','mapped to supported fields')}; ${pack.report.unmapped} ${B('נשמרו רק בקובץ המקור ולא מופו','were not mapped into application fields')}. ${B('ביטויי OWL אנונימיים נקראים אך אינם הופכים אוטומטית לקטגוריות. אין מנוע הסקה.','Anonymous OWL expressions are read but do not automatically become categories. No reasoning engine is used.')}</p>${pack.warnings?.map(w=>`<p>${esc(w)}</p>`).join('')||''}</details>`:''}
<div class="toolbar"><input id="catalogQuery" type="search" value="${esc(ui.catalogQuery||'')}" placeholder="${B('חיפוש בעברית, באנגלית או לפי URI','Search Hebrew, English or URI')}" aria-label="${B('חיפוש באוצר המילים','Search vocabulary')}"><select id="catalogKind">${opt('',B('מושגים ויחסים','Concepts and relations'),ui.catalogKind||'')}${opt('concept',B('מושגים בלבד','Concepts only'),ui.catalogKind||'')}${opt('relation',B('סוגי קשרים בלבד','Relation types only'),ui.catalogKind||'')}</select>${btn('catalog-search',B('חיפוש','Search'))}${btn('catalog-clear',B('איפוס','Reset'))}</div>
<details style="margin-top:16px" ${ui.catalogGraph?'open':''} id="catalogGraph"><summary>${B('רשת המקור','Source network')} · ${B('עד 160 צמתים מן המסנן הנוכחי','up to 160 nodes from the current filter')}</summary><p class="small muted">${B('קשתות מציגות היררכיה, קשרי SKOS ותחום/טווח מפורשים של יחסים. אלו קשרים במודל, לא קשרים בין דברים שסומנו בעמוד.','Edges show hierarchy, SKOS relationships and explicit property domains/ranges. These describe the model, not annotated occurrences on a page.')}</p>${graph(terms.map(t=>({id:t.id,label:L(t),color:t.kind==='relation'?'#b68a42':t.layer==='meaning'?'#79619b':'#467d9a'})),edges,'pack')}</details>
<div class="toolbar" style="margin:18px 0 10px">${btn('catalog-select-filtered',B('בחירת כל תוצאות החיפוש','Select all search results'))}${btn('pack-none',B('ניקוי הבחירה','Clear selection'))}<span class="muted small">${terms.length} ${B('תוצאות','results')}</span></div><div class="catalog-list">${visible.map(t=>`<div class="catalog-row"><input type="checkbox" data-pack-term="${esc(t.id)}" ${selection.has(t.id)?'checked':''} aria-label="${esc(L(t))}"><div><b dir="auto">${esc(L(t))}</b> <span class="badge ${t.kind==='relation'?'meaning':''}">${t.kind==='relation'?B('יחס','Relation'):B('מושג','Concept')}</span><div class="definition" dir="auto">${esc(L(t,'definition'))}</div><div class="small muted">${(t.parents||[]).map(id=>esc(L(by.get(id))||id.split(/[\/#]/).pop())).join(' · ')}</div></div>${btn('graph-pack',B('פרטים','Details'),'',`data-id="${esc(t.id)}"`)}</div>`).join('')||`<p class="muted" style="padding:16px">${B('אין תוצאות במסנן הזה.','No results for this filter.')}</p>`}</div><div class="toolbar" style="margin-top:12px">${btn('catalog-prev','‹','',page?'':'disabled')}<span>${page+1} / ${Math.max(1,Math.ceil(terms.length/70))}</span>${btn('catalog-next','›','',(page+1)*70<terms.length?'':'disabled')}</div>
<div class="panel" style="margin-top:18px;background:#f0f5ed"><div class="toolbar"><label class="inline"><input id="catalogParents" type="checkbox" ${ui.includeParents!==false?'checked':''}>${B('לכלול גם מושגי אב','Include broader concepts')}</label>${infoButton('parents')}<label>${B('שכבת הנתונים','Data layer')}<select id="packLayer">${opt('',B('לפי הערכה; תיאור כברירת מחדל','From pack; descriptive by default'))}${opt('visual',B('תיאור חזותי','Visual description'))}${opt('structure',B('מבנה ורצף','Structure and sequence'))}${opt('meaning',B('פרשנות ומשמעות','Interpretation and meaning'))}</select></label>${btn('adopt-pack',B('אימוץ הערכים שנבחרו','Adopt selected terms'),'primary')}</div><p class="small muted">${B('השמות בכל השפות, ההגדרות, מזהי המקור והקשרים הנתמכים יישמרו. אימוץ מקור אינו קובע שהקטגוריות מתאימות לשאלת המחקר שלכם.','Labels in all available languages, definitions, source identifiers and supported links are retained. Adopting a vocabulary does not establish that its categories suit your research question.')}</p></div></div></section></div>`;}
function renderAnnotate(){const im=getImage();if(!im)return heading(T("תיוג ופרשנות"),T("קודם מוסיפים חומר"),T("העלו תמונות באזור האוסף כדי להתחיל."))+btn('go-collection',T("מעבר לאוסף"),'primary');ui.imageId=im.id;const anns=P.annotations.filter(a=>a.imageId===im.id),sel=P.annotations.find(a=>a.id===ui.selected),claims=P.claims.filter(c=>c.evidence.some(id=>anns.some(a=>a.id===id)));
return heading(T("תיוג ופרשנות"),esc(L(im,'title')||L(im,'name')),`${T("עמוד ")}${P.images.indexOf(im)+1} ${T("ברצף · ")}${esc(L(im,'work')||T("טרם הוגדרה יצירה"))} · ${T("מספר מקור: ")}${esc(im.page||'—')}`,btn('new-claim',T("＋ טענה פרשנית"),'primary')+btn('new-link',T("＋ קשר")))+
`<div class="workspace"><section class="panel canvaspanel"><div class="canvastools">${[['select',T("בחירה")],['rect',T("מלבן")],['polygon',T("מצולע")],['point',T("נקודה")],['move',T("הזזת אזור")]].map(([id,l])=>btn('tool',l,ui.tool===id?'active':'',`data-id="${id}"`)).join('')}${btn('page-tag',T("תיוג עמוד שלם"))}<label class="inline">${T("זום ")}<select id="zoom">${[75,100,150,200,300].map(z=>opt(z,z+'%',ui.zoom)).join('')}</select></label></div><div class="stage-scroll"><div class="stage" id="stage" style="width:${ui.zoom}%"><img id="sourceImage" src="${esc(assets[im.id])}" alt="${esc(L(im,'title')||L(im,'name'))}"><svg id="overlay" viewBox="0 0 ${im.width} ${im.height}" aria-label="${T("סימונים על התמונה")}"></svg></div></div><div class="canvastools small muted" id="toolHint">${toolHint()}</div><div class="filmstrip">${P.images.map((x,i)=>`<button data-action="annotate-image" data-id="${x.id}" class="${x.id===im.id?'active':''}" title="${esc(L(x,'title')||L(x,'name'))}"><img src="${esc(assets[x.id])}" alt="${i+1}"><div>${i+1}</div></button>`).join('')}</div></section>
<aside><div class="panel"><h3>${T("מה מזוהה בעמוד?")}</h3><p class="small muted">${T("בחרו כלי וסמנו אזור. ערכי תיאור ומבנה נשמרים בסימון; משמעות נשמרת בטענה נפרדת.")}</p>${sel?`<div class="notice"><b>${esc(L(sel,'label')||T("אזור מסומן"))}</b><br>${sel.conceptIds.map(id=>esc(conceptLabel(id))).join(' · ')}<div class="toolbar">${btn('edit-annotation',T("עריכה"),'',`data-id="${sel.id}"`)}${btn('redraw-annotation',T("סימון מחדש"),'',`data-id="${sel.id}"`)}${btn('claim-selected',T("＋ פרשנות"),'',`data-id="${sel.id}"`)}${btn('delete-annotation',T("מחיקה"),'danger',`data-id="${sel.id}"`)}</div></div>`:''}<div class="scroll" style="max-height:320px">${anns.map((a,i)=>`<div class="annotitem ${a.id===ui.selected?'selected':''}" data-action="select-annotation" data-id="${a.id}"><b>${i+1}. ${esc(L(a,'label')||a.conceptIds.map(conceptLabel).join(', ')||T("אזור ללא תיאור"))}</b><br><span class="small muted">${esc(a.author||T("ללא שם"))} · ${a.geometry.type==='page'?T("עמוד שלם"):a.geometry.type==='rect'?T("מלבן"):a.geometry.type==='point'?T("נקודה"):T("מצולע")}</span></div>`).join('')||H("<p class=\"muted\">טרם סומנו אזורים.</p>")}</div></div>
<div class="panel"><h3>${T("מה המשמעות?")}</h3>${claims.map(c=>`<div class="claim"><b>${esc(L(c,'text')||c.conceptIds.map(conceptLabel).join(', '))}</b><div>${c.conceptIds.map(id=>`<span class="badge meaning">${esc(conceptLabel(id))}</span>`).join('')}</div><small>${c.evidence.length} ${T("ראיות · ")}${esc(c.author||T("ללא שם"))} · ${esc(T(c.confidence))}</small><div class="toolbar">${btn('edit-claim',T("עריכה"),'',`data-id="${c.id}"`)}${btn('delete-claim',T("מחיקה"),'danger',`data-id="${c.id}"`)}</div></div>`).join('')||H("<p class=\"small muted\">אותו אזור יכול לתמוך בכמה טענות, וטענה יכולה להתבסס על כמה אזורים.</p>")}</div>
<div class="panel"><h3>${T("מה נבדק?")}</h3><p class="small muted">${T("סמנו קבוצה רק לאחר שבדקתם את העמוד ביחס אליה. כך נבחין בין אפס מופעים לבין עמוד שטרם נבדק. תיוג חיובי מוצג גם אם הבדיקה טרם הושלמה.")}</p>${P.groups.map(g=>`<label class="inline"><input type="checkbox" data-checked-group="${g.id}" ${im.checkedGroups.includes(g.id)?'checked':''}>${esc(L(g,'label'))}</label>`).join('')||H("<p class=\"small\">הוסיפו קבוצות באזור המודל.</p>")}</div></aside></div>
<div class="panel"><div class="sectionhead"><h2>${T("קשרים הקשורים לעמוד")}</h2>${btn('new-link',T("＋ קשר"))}</div>${relationsTable(P.relations.filter(r=>endpointImages(r.source).includes(im.id)||endpointImages(r.target).includes(im.id)))}</div>`;}
function toolHint(){return {select:T("לחצו על אזור כדי לבחור אותו. לחצו על ״עריכה״ להוספת תגיות."),rect:T("גררו מלבן סביב האזור הרצוי."),point:T("לחצו להצבת נקודה."),polygon:T("לחצו להוספת קודקודים. לסיום: לחיצה כפולה או Enter. לביטול: Escape."),move:T("גררו אזור קיים כדי להזיז את כל קודקודיו.")}[ui.tool];}
function endpointImages(id){const a=P.annotations.find(x=>x.id===id);if(a)return [a.imageId];const c=P.claims.find(x=>x.id===id);if(c)return [...new Set(c.evidence.flatMap(endpointImages))];return P.images.some(x=>x.id===id)?[id]:[];}
function relationsTable(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>${T("מקור")}</th><th>${T("יחס")}</th><th>${T("יעד")}</th><th>${T("הסבר")}</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(L(nodeInfo(r.source),'label'))}</td><td>${esc(L(P.relationTypes.find(t=>t.id===r.typeId),'label'))}</td><td>${esc(L(nodeInfo(r.target),'label'))}</td><td>${esc(L(r,'note'))}</td><td>${btn('delete-link',T("מחיקה"),'danger',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:H("<p class=\"muted small\">עדיין אין קשרים. אפשר לחבר סימונים, טענות, עמודים ומושגים.</p>");}
function graph(nodes,edges,action){
 nodes=nodes.slice(0,160);const ids=new Set(nodes.map(n=>n.id));edges=edges.filter(e=>ids.has(e.source)&&ids.has(e.target));if(!nodes.length)return H("<div class=\"empty\">אין עדיין צמתים להצגה.</div>");
 const W=1100,by=new Map(nodes.map(n=>[n.id,{...n}])),adj=new Map(nodes.map(n=>[n.id,new Set()]));for(const e of edges){adj.get(e.source).add(e.target);adj.get(e.target).add(e.source);}const seen=new Set(),components=[];for(const n of nodes){if(seen.has(n.id))continue;const comp=[],queue=[n.id];seen.add(n.id);while(queue.length){const id=queue.shift();comp.push(by.get(id));for(const next of adj.get(id))if(!seen.has(next)){seen.add(next);queue.push(next);}}components.push(comp);}components.sort((a,b)=>b.length-a.length);
 const connected=components.filter(c=>c.length>1),isolated=components.filter(c=>c.length===1).flat();let rowY=20,col=0,rowHeight=0;
 for(const comp of connected){const wide=comp.length>9,cw=wide?W:W/2,ch=Math.max(320,Math.ceil(comp.length/5)*125);if(wide&&col){rowY+=rowHeight;col=0;rowHeight=0;}const left=col*W/2,top=rowY;rowHeight=Math.max(rowHeight,ch);
  if(action==='concept'||action==='pack'){
   const compIds=new Set(comp.map(n=>n.id)),parents=new Map(comp.map(n=>[n.id,edges.filter(e=>e.source===n.id&&compIds.has(e.target)).map(e=>e.target)]));const depths=new Map();function depth(id,vis=new Set()){if(depths.has(id))return depths.get(id);if(vis.has(id))return 0;const path=new Set([...vis,id]),ps=parents.get(id)||[];const d=ps.length?1+Math.max(...ps.map(p=>depth(p,path))):0;depths.set(id,Math.min(d,6));return Math.min(d,6);}comp.forEach(n=>depth(n.id));const max=Math.max(...depths.values());for(let d=0;d<=max;d++){const level=comp.filter(n=>depths.get(n.id)===d);level.forEach((n,i)=>{n.x=left+cw*(i+1)/(level.length+1);n.y=top+60+(max?d*(ch-145)/max:0);});}
  }else{
   comp.sort((a,b)=>adj.get(b.id).size-adj.get(a.id).size);comp.forEach((n,i)=>{n.x=left+cw/2+(i?Math.cos((i-1)*2*Math.PI/Math.max(1,comp.length-1))*cw*.29:0);n.y=top+ch/2+(i?Math.sin((i-1)*2*Math.PI/Math.max(1,comp.length-1))*ch*.29:0);});
   for(let step=0;step<90;step++){for(let i=0;i<comp.length;i++)for(let j=i+1;j<comp.length;j++){const a=comp[i],b=comp[j],dx=a.x-b.x||.1,dy=a.y-b.y||.1,d2=Math.max(100,dx*dx+dy*dy),f=1900/d2*.07;a.x+=dx*f;b.x-=dx*f;a.y+=dy*f;b.y-=dy*f;}for(const e of edges){const a=comp.find(n=>n.id===e.source),b=comp.find(n=>n.id===e.target);if(!a||!b)continue;const dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,f=(d-160)*.016;a.x+=dx/d*f;b.x-=dx/d*f;a.y+=dy/d*f;b.y-=dy/d*f;}comp.forEach(n=>{n.x=Math.max(left+90,Math.min(left+cw-90,n.x));n.y=Math.max(top+50,Math.min(top+ch-80,n.y));});}
  }
  if(wide){rowY+=rowHeight;rowHeight=0;col=0;}else if(++col===2){rowY+=rowHeight;rowHeight=0;col=0;}
 }
 if(col)rowY+=rowHeight;const isolatedStart=rowY+(connected.length&&isolated.length?45:0);isolated.forEach((n,i)=>{n.x=100+(i%6)*180;n.y=isolatedStart+35+Math.floor(i/6)*115;});const H=Math.max(320,isolatedStart+Math.ceil(isolated.length/6)*115+25,rowY+25);const marker='arrow-'+C.uid();
 function lines(label,max=22){const words=String(label).split(' '),out=[''];for(const word of words){let last=out.length-1;if((out[last]+' '+word).trim().length>max&&out[last])out.push(word);else out[last]=(out[last]+' '+word).trim();}if(out.length>2)out.splice(1,out.length-1,out.slice(1).join(' ').slice(0,max)+'…');return out;}
 return `<div class="graphwrap" style="max-height:690px"><svg viewBox="0 0 ${W} ${H}" style="height:auto;min-width:900px;aspect-ratio:${W}/${H}" role="img" aria-label="${T("רשת: ")}${nodes.length} ${T("צמתים, ")}${edges.length} ${T("קשרים")}"><defs><marker id="${marker}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#8a9c92"/></marker></defs>${connected.length&&isolated.length?`<line x1="35" y1="${isolatedStart-25}" x2="1065" y2="${isolatedStart-25}" stroke="#d9dfd4"/><text x="550" y="${isolatedStart-3}" text-anchor="middle" direction="rtl" fill="#64746c">${T("מושגים ללא קשרים בתצוגה הזו")}</text>`:''}${edges.map(e=>{const a=by.get(e.source),b=by.get(e.target),dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,x1=a.x+dx/d*23,y1=a.y+dy/d*23,x2=b.x-dx/d*28,y2=b.y-dy/d*28;const duplicates=edges.filter(q=>q.source===e.source&&q.target===e.target),off=duplicates.length>1?(duplicates.indexOf(e)-(duplicates.length-1)/2)*40:0;const label=e.label||'';return `<path d="M${x1},${y1} Q${(a.x+b.x)/2-dy/d*off},${(a.y+b.y)/2+dx/d*off} ${x2},${y2}" stroke="#91a49a" stroke-width="1.7" fill="none" marker-end="url(#${marker})"><title>${esc(label)}</title></path><text class="edge-label" text-anchor="middle" direction="auto" x="${(a.x+b.x)/2-dy/d*off}" y="${(a.y+b.y)/2+dx/d*off-9}">${esc(label.length>28?label.slice(0,26)+'…':label)}</text>`;}).join('')}${nodes.map(original=>{const n=by.get(original.id);return `<g class="node" data-action="graph-${action}" data-id="${esc(n.id)}" role="button" tabindex="0"><title>${esc(L(n,'label'))}</title><circle cx="${n.x}" cy="${n.y}" r="21" fill="${esc(n.color||'#1d6658')}"/><text text-anchor="middle" x="${n.x}" y="${n.y+40}" direction="auto">${lines(n.label).map((l,i)=>`<tspan x="${n.x}" dy="${i?17:0}">${esc(l)}</tspan>`).join('')}</text></g>`;}).join('')}</svg></div>`;
}
function groupForm(id){const old=P.groups.find(g=>g.id===id);openDialog(biHTML(`<h2>${old?T("עריכת קבוצה"):T("קבוצה חדשה")}</h2><form id="editForm" class="stack"><label>${T("שם הקבוצה")}<input id="f-label" required value="${esc(L(old,'label'))}" placeholder="${T("למשל: צבעים")}"></label><div class="fields"><label>${T("שכבה")}<select id="f-layer">${Object.entries(C.layers).map(([k,l])=>opt(k,T(l),old?.layer||'visual')).join('')}</select></label><label>${T("בחירה")}<select id="f-selection">${opt('multiple',T("כמה ערכים"),old?.selection||'multiple')}${opt('single',T("ערך יחיד"),old?.selection||'multiple')}</select></label><label>${T("צבע בתרשימים")}<input id="f-color" type="color" value="${esc(old?.color||'#1d6658')}"></label></div><button class="primary">${T("שמירת קבוצה")}</button></form>`,old,[["f-label","label"]]),()=>{$('editForm').onsubmit=e=>{e.preventDefault();const layer=$('f-layer').value,selection=$('f-selection').value;const groupId=old?.id;if(old&&old.layer!==layer&&P.concepts.some(c=>c.groupId===id)){toast(T("כדי לשמור על הפרדת השכבות, שינוי שכבה אפשרי בקבוצה ריקה בלבד."));return;}if(old&&selection==='single'){const ids=new Set(P.concepts.filter(c=>c.groupId===id).map(c=>c.id));if([...P.annotations,...P.claims].some(a=>a.conceptIds.filter(x=>ids.has(x)).length>1)){toast(T("יש פריטים עם כמה ערכים בקבוצה; יש לתקן אותם לפני מעבר לבחירה יחידה."));return;}}const val={id:groupId||C.uid(),label:$('f-label').value.trim(),layer,selection,color:$('f-color').value};attachBi(val,old);if(!val.label)return;if(mutate(T("שמירת קבוצה"),()=>{if(old)Object.assign(old,val);else P.groups.push(val);}))closeDialog();};});}
function conceptForm(id,groupId){if(!P.groups.length){toast(T("צרו קודם קבוצה או הוסיפו ערכה."));groupForm();return;}const c=P.concepts.find(c=>c.id===id);openDialog(biHTML(`<h2>${c?T("עריכת מושג"):T("מושג חדש")}</h2><form id="editForm" class="stack"><div class="fields"><label>${T("תווית")}<input id="f-label" required value="${esc(L(c,'label'))}"></label><label>${T("קבוצה")}<select id="f-group">${P.groups.map(g=>opt(g.id,L(g,'label'),c?.groupId||groupId||P.groups[0].id)).join('')}</select></label><label class="wide">${T("הגדרה והנחיות תיוג")}<textarea id="f-definition">${esc(L(c,'definition'))}</textarea></label><label class="wide">${T("תתי־סוג של (אפשר כמה הורים)")}<select id="f-parents" multiple size="5">${P.concepts.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${c?.parents.includes(x.id)?'selected':''}>${esc(L(x,'label'))}</option>`).join('')}</select><small>Ctrl ${T("לבחירה מרובה. ״סוג של״ שונה מ״נמצא בתוך״.")}</small></label><label class="wide">${T("מזהה מקור חיצוני (URI)")}<input id="f-uri" value="${esc(c?.uri)}" dir="ltr"></label></div><div class="toolbar"><button class="primary">${T("שמירת מושג")}</button>${c?btn('delete-concept',T("מחיקה"),'danger',`data-id="${c.id}"`):''}</div></form>`,c,[["f-label","label"],["f-definition","definition"]]),()=>{$('editForm').onsubmit=e=>{e.preventDefault();const val={id:id||C.uid(),label:$('f-label').value.trim(),groupId:$('f-group').value,definition:$('f-definition').value.trim(),parents:[...$('f-parents').selectedOptions].map(x=>x.value),uri:$('f-uri').value.trim(),source:c?.source||T("מושג מקומי")};attachBi(val,c);if(!val.label)return;if(c&&groupOf(c)?.layer!==P.groups.find(g=>g.id===val.groupId)?.layer&&[...P.annotations,...P.claims].some(a=>a.conceptIds.includes(id))){toast(T("לא ניתן להעביר מושג שכבר תויג לשכבה אחרת."));return;}if(mutate(T("שמירת מושג"),()=>{if(c)Object.assign(c,val);else P.concepts.push(val);}))closeDialog();};});}
function relationTypeForm(id){const r=P.relationTypes.find(x=>x.id===id);openDialog(biHTML(`<h2>${r?T("עריכת סוג קשר"):T("סוג קשר חדש")}</h2><form id="editForm" class="stack"><label>${T("שם היחס")}<input id="f-label" required value="${esc(L(r,'label'))}" placeholder="${T("למשל: מייצג את")}"></label><div class="fields"><label>${T("משפחת הקשר")}<select id="f-kind">${['spatial','reading','temporal','interpretive','identity','evidence','conceptual','custom'].map(k=>opt(k,relationKind(k),r?.kind||'custom')).join('')}</select></label>${['from','to'].map(k=>`<label>${k==='from'?T("סוג מקור"):T("סוג יעד")}<select id="f-${k}">${['any','annotation','claim','image','concept'].map(t=>opt(t,endpointType(t),r?.[k]||'any')).join('')}</select></label>`).join('')}</div><button class="primary">${T("שמירה")}</button></form>`,r,[["f-label","label"]]),()=>{$('editForm').onsubmit=e=>{e.preventDefault();const val={id:id||C.uid(),label:$('f-label').value.trim(),kind:$('f-kind').value,from:$('f-from').value,to:$('f-to').value};attachBi(val,r);if(!val.label)return;const existing=[...P.relations,...P.conceptLinks].filter(x=>x.typeId===id);if(existing.some(x=>(val.from!=='any'&&nodeInfo(x.source).type!==val.from)||(val.to!=='any'&&nodeInfo(x.target).type!==val.to))){toast(T("ההגבלה החדשה אינה מתאימה לחלק מהקשרים הקיימים."));return;}mutate(T("שמירת סוג קשר"),()=>r?Object.assign(r,val):P.relationTypes.push(val));closeDialog();};});}
function conceptChecklist(selected,allowMeaning=false){return P.groups.filter(g=>allowMeaning?g.layer==='meaning':g.layer!=='meaning').map(g=>`<fieldset style="border:0;border-bottom:1px solid var(--line);padding:8px 0"><legend>${esc(L(g,'label'))} · ${g.selection==='single'?T("בחירה יחידה"):T("בחירה מרובה")}</legend>${P.concepts.filter(c=>c.groupId===g.id).map(c=>`<label title="${esc(L(c,'definition'))}"><input data-concept-check="${c.id}" data-group="${g.id}" type="checkbox" ${selected.includes(c.id)?'checked':''}>${esc(L(c,'label'))}</label>`).join('')}</fieldset>`).join('')||H("<p class=\"small muted\">לא הוגדרו עדיין מושגים בשכבה הזו. אפשר לשמור טקסט חופשי ולהוסיף מושגים בהמשך.</p>");}
function bindSingleChoice(){document.querySelectorAll('[data-concept-check]').forEach(el=>el.onchange=()=>{if(el.checked&&P.groups.find(g=>g.id===el.dataset.group)?.selection==='single')document.querySelectorAll(`[data-concept-check][data-group="${el.dataset.group}"]`).forEach(other=>{if(other!==el)other.checked=false;});});}
function annotationForm(id,geometry){const a=P.annotations.find(x=>x.id===id);const im=getImage();openDialog(biHTML(`<h2>${a?T("עריכת סימון"):T("מה מזוהה באזור?")}</h2><form id="editForm" class="stack"><label>${T("תיאור קצר")}<input id="f-label" value="${esc(L(a,'label'))}" placeholder="${T("למשל: דמות ליד גדר")}"></label><div class="checklist">${conceptChecklist(a?.conceptIds||[])}</div><label>${T("הערה על הזיהוי")}<textarea id="f-note">${esc(L(a,'note'))}</textarea></label><p class="small muted">${T("פרשנות תתווסף כטענה נפרדת לאחר שמירת הסימון.")}</p><button class="primary">${T("שמירת סימון")}</button></form>`,a,[["f-label","label"],["f-note","note"]]),()=>{bindSingleChoice();$('editForm').onsubmit=e=>{e.preventDefault();const val={id:id||C.uid(),imageId:a?.imageId||im.id,label:$('f-label').value.trim(),note:$('f-note').value.trim(),conceptIds:[...document.querySelectorAll('[data-concept-check]:checked')].map(x=>x.dataset.conceptCheck),geometry:geometry||a?.geometry,author:a?.author||P.author,created:a?.created||C.now(),updated:C.now()};attachBi(val,a);if(!val.label&&!val.conceptIds.length){toast(T("הוסיפו תיאור קצר או בחרו מושג."));return;}mutate(T("שמירת סימון"),()=>{if(a)Object.assign(a,val);else P.annotations.push(val);ui.selected=val.id;});closeDialog();};});}
function claimForm(id,evidence){if(!P.annotations.length){toast(T("סמנו תחילה אזור או עמוד שלם שישמש ראיה."));return;}const c=P.claims.find(x=>x.id===id);const evid=c?.evidence||evidence||[];openDialog(biHTML(`<h2>${c?T("עריכת טענה"):T("טענה פרשנית חדשה")}</h2><form id="editForm" class="stack"><label>${T("מה נטען?")}<textarea id="f-text" placeholder="${T("למשל: הגדר מדגישה את חוויית הכליאה")}">${esc(L(c,'text'))}</textarea></label><div class="checklist">${conceptChecklist(c?.conceptIds||[],true)}</div><h3>${T("הראיות לטענה")}</h3><div class="checklist">${P.annotations.map(a=>`<label><input type="checkbox" data-evidence="${a.id}" ${evid.includes(a.id)?'checked':''}>${esc(annotationLabel(a))}</label>`).join('')}</div><label>${T("הסבר / מקור לפרשנות")}<textarea id="f-note">${esc(L(c,'note'))}</textarea></label><label>${T("מידת ודאות")}<select id="f-confidence">${['מוצע לדיון','סביר','מבוסס'].map(x=>opt(x,x,c?.confidence||'מוצע לדיון')).join('')}</select></label><button class="primary">${T("שמירת טענה")}</button></form>`,c,[["f-text","text"],["f-note","note"]]),()=>{bindSingleChoice();$('editForm').onsubmit=e=>{e.preventDefault();const val={id:id||C.uid(),text:$('f-text').value.trim(),conceptIds:[...document.querySelectorAll('[data-concept-check]:checked')].map(x=>x.dataset.conceptCheck),evidence:[...document.querySelectorAll('[data-evidence]:checked')].map(x=>x.dataset.evidence),note:$('f-note').value.trim(),confidence:$('f-confidence').value,author:c?.author||P.author,created:c?.created||C.now(),updated:C.now()};attachBi(val,c);if(!val.evidence.length||(!val.text&&!val.conceptIds.length)){toast(T("נדרשים תוכן לטענה ולפחות סימון אחד כראיה."));return;}mutate(T("שמירת טענה פרשנית"),()=>c?Object.assign(c,val):P.claims.push(val));closeDialog();};});}
function relationForm(conceptsOnly=false){const nodes=conceptsOnly?P.concepts:[...P.annotations,...P.claims,...P.images,...P.concepts];if(nodes.length<2){toast(T("דרושים שני פריטים לפחות."));return;}openDialog(biHTML(`<h2>${conceptsOnly?T("קשר בין מושגים"):T("יצירת קשר")}</h2><form id="editForm" class="stack"><label>${T("סוג הקשר")}<select id="f-type">${P.relationTypes.filter(t=>t.valueType!=='literal').filter(t=>!conceptsOnly||(['any','concept'].includes(t.from)&&['any','concept'].includes(t.to))).map(t=>opt(t.id,L(t,'label'))).join('')}</select></label><label>${T("פריט מקור")}<select id="f-source"></select></label><label>${T("פריט יעד")}<select id="f-target"></select></label><label>${T("הסבר / ראיה")}<textarea id="f-note"></textarea></label><p class="small muted">${T("החץ ייצא מהמקור אל היעד. קשר מרחבי בדף מתייחס למיקום בתמונה; קשר בזמן הסיפור מתייחס לאירועים המתוארים.")}</p><button class="primary">${T("יצירת קשר")}</button></form>`,null,[["f-note","note"]]),()=>{function update(){const t=P.relationTypes.find(x=>x.id===$('f-type').value);for(const [field,type] of [['source',t?.from],['target',t?.to]])$('f-'+field).innerHTML=nodes.filter(n=>type==='any'||nodeInfo(n.id).type===type).map(n=>opt(n.id,endpointType(nodeInfo(n.id).type)+' · '+L(nodeInfo(n.id),'label'),field==='source'?ui.selected:'')).join('');if($('f-target').options.length>1)$('f-target').selectedIndex=1;}$('f-type').onchange=update;update();$('editForm').onsubmit=e=>{e.preventDefault();const source=$('f-source').value,target=$('f-target').value,typeId=$('f-type').value;if(!source||!target||!typeId||source===target){toast(T("בחרו שני פריטים שונים וסוג קשר."));return;}const r={id:C.uid(),source,target,typeId,note:$('f-note').value.trim(),author:P.author,created:C.now()};attachBi(r,null);mutate(T("יצירת קשר"),()=>(conceptsOnly?P.conceptLinks:P.relations).push(r));closeDialog();};});}
function analysisImages(){return P.images.filter(im=>!ui.work||im.work===ui.work);}
function analysisConcepts(){return P.concepts.filter(c=>ui.analysisLayer==='all'||groupOf(c)?.layer===ui.analysisLayer);}
function matches(id,im){return C.count(P,id,im,ui.descendants,ui.author);}
function renderAnalysis(){const ims=analysisImages(),concepts=analysisConcepts(),workNames=[...new Set(P.images.map(i=>i.work).filter(Boolean))],authors=[...new Set([...P.annotations,...P.claims].map(x=>x.author).filter(Boolean))];let html=heading(T("קריאה מרחוק"),T("מה מצטבר לאורך הרצף?"),T("כל מספר נשען על סימונים וטענות שאפשר לפתוח מחדש. בדקו את יחידת הספירה ואת היקף הבדיקה לפני שמסיקים מסקנה."),btn('export-data',T("ייצוא טבלאות ונתונים"),'primary'));
html+=`<div class="panel toolbar"><label>${T("יצירה")}<select id="analysisWork">${opt('',T("כל היצירות"),ui.work)}${workNames.map(w=>opt(w,w,ui.work)).join('')}</select></label><label>${T("שכבת מושגים")}<select id="analysisLayer">${opt('all',T("כל השכבות"),ui.analysisLayer)}${Object.entries(C.layers).map(([k,l])=>opt(k,T(l),ui.analysisLayer)).join('')}</select></label><label>${T("מתייג/ת")}<select id="analysisAuthor">${opt('',T("כולם"),ui.author)}${authors.map(a=>opt(a,a,ui.author)).join('')}</select></label><label>${T("יחידת ספירה")}<select id="analysisMetric">${opt('occurrences',T("סימונים / טענות נפרדות"),ui.metric)}${opt('pages',T("עמודים עם הופעה"),ui.metric)}${opt('works',T("יצירות עם הופעה"),ui.metric)}</select></label><label class="inline"><input id="analysisDesc" type="checkbox" ${ui.descendants?'checked':''}>${T("כולל תתי־סוגים")}</label></div>`;
const ann=P.annotations.filter(a=>ims.some(i=>i.id===a.imageId)&&(!ui.author||a.author===ui.author)&&(ui.analysisLayer==='all'||(ui.analysisLayer!=='meaning'&&a.conceptIds.some(id=>groupOf(P.concepts.find(c=>c.id===id))?.layer===ui.analysisLayer))));const claims=P.claims.filter(c=>(ui.analysisLayer==='all'||ui.analysisLayer==='meaning')&&(!ui.author||c.author===ui.author)&&c.evidence.some(id=>P.annotations.some(a=>a.id===id&&ims.some(im=>im.id===a.imageId))));
html+=`<div class="metrics">${[[ims.length,T("עמודים ברצף הנבחר")],[ann.length,T("סימונים")],[claims.length,T("טענות פרשניות")],[concepts.length,T("מושגים בשכבה הנבחרת")]].map(([n,l])=>`<div class="panel"><div class="metric">${n}</div><div class="small muted">${l}</div></div>`).join('')}</div><div class="tabs">${[['heat',T("מפת חום ברצף")],['frequency',T("שכיחויות")],['co',T("הופעה משותפת")],['network',T("רשת הראיות והקשרים")],['table',T("טבלת הסימונים והטענות")]].map(([id,l])=>btn('analysis-tab',l,ui.analysis===id?'active':'',`data-id="${id}"`)).join('')}</div>`;
if(!ims.length||!P.annotations.length)return html+`<div class="empty"><h2>${T("מהתיוג אל הדפוס המצטבר")}</h2><p>${T("אחרי יצירת סימונים וטענות תוכלו להשוות את הופעתם לאורך העמודים ולחזור מתוצאות הניתוח אל המקור.")}</p>${btn('go-annotate',T("מעבר לתיוג"),'primary')}</div>`;
if(ui.analysis==='heat'){const max=Math.max(1,...concepts.flatMap(c=>ims.map(im=>matches(c.id,im.id).length)));html+=`<div class="panel"><h2>${T("מפת חום · מושגים × עמודים")}</h2><p class="small muted">${T("התאים סופרים סימונים או טענות נפרדות בכל עמוד, ללא קשר למדד שנבחר לתרשים השכיחויות. טענה אחת עם כמה ראיות באותו עמוד נספרת פעם אחת. סדר העמודות הוא סדר האוסף, מימין לשמאל. לחיצה על תא פותחת את הראיות.")}</p><div class="legend"><span><i class="colorbox" style="background:#e8eae4"></i>0 = ${T("הקבוצה נבדקה, לא נמצא")}</span><span><i class="colorbox" style="background:repeating-linear-gradient(45deg,#eee,#eee 3px,#bbb 4px)"></i>— = ${T("טרם הושלמה בדיקת הקבוצה")}</span><span><i class="colorbox" style="background:#1d6658"></i>${T("מספר = נמצאו מופעים")}</span></div>${ui.author?H("<div class=\"notice\">סטטוס הבדיקה הוא ברמת הפרויקט; מסנן המתייג משנה את הספירות בלבד. אפס מסונן אינו מוכיח שכל מתייג בדק את העמוד.</div>"):''}<div class="tablewrap"><table><thead><tr><th>${T("מושג / עמוד")}</th>${ims.map(im=>`<th>${btn('annotate-image',String(P.images.indexOf(im)+1),'',`data-id="${im.id}" title="${esc(L(im,'title')||L(im,'name'))}"`)}<br><small>${esc(im.page||'')}</small></th>`).join('')}</tr></thead><tbody>${concepts.map(c=>`<tr><th>${esc(L(c,'label'))}<br><small class="muted">${esc(L(groupOf(c),'label'))}</small></th>${ims.map(im=>{const n=matches(c.id,im.id).length,checked=im.checkedGroups.includes(c.groupId);return `<td><button data-action="drill" data-concept="${c.id}" data-image="${im.id}" class="heat ${!n&&!checked?'unchecked':''}" style="background:${n?`rgba(29,102,88,${.16+.72*n/max})`:'#e8eae4'};color:${n/max>.6?'white':'#183e38'}" title="${esc(L(c,'label')+' · '+(L(im,'title')||L(im,'name')))}">${n||(!checked?'—':'0')}${n&&!checked?'*':''}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">* ${T("נמצאו מופעים אך בדיקת הקבוצה בעמוד טרם הושלמה. סטטוס הבדיקה מסומן ידנית, ואינו הוכחה למיצוי התוכן.")}</p></div>`;}
if(ui.analysis==='frequency'){const rows=concepts.map(c=>{const match=ims.flatMap(im=>matches(c.id,im.id)),uniq=[...new Map(match.map(m=>[m.id,m])).values()];const pages=ims.filter(im=>matches(c.id,im.id).length);const works=new Set(pages.map(im=>im.work||T("(ללא יצירה)")));return {c,n:ui.metric==='occurrences'?uniq.length:ui.metric==='pages'?pages.length:works.size};}).sort((a,b)=>b.n-a.n);const max=Math.max(1,...rows.map(r=>r.n));html+=`<div class="panel"><h2>${T("שכיחויות · ")}${ui.metric==='occurrences'?T("סימונים וטענות נפרדים"):ui.metric==='pages'?T("עמודים עם הופעה"):T("יצירות עם הופעה")}</h2><p class="small muted">${T("טענה הנתמכת בכמה עמודים נספרת פעם אחת במדד סימונים / טענות. תתי־סוגים נכללים רק אם האפשרות נבחרה. הספירות גולמיות, ללא נרמול לאורך היצירה.")}</p>${rows.map(({c,n})=>`<button class="barbutton" data-action="drill" data-concept="${c.id}"><div class="chartrow"><span>${esc(L(c,'label'))}</span><div class="bar"><i style="width:${n/max*100}%;background:${esc(groupOf(c)?.color)}"></i></div><b>${n}</b></div></button>`).join('')}</div>`;}
if(ui.analysis==='co'){const active=concepts.filter(c=>ims.some(im=>matches(c.id,im.id).length)).slice(0,35);html+=`<div class="panel"><h2>${T("הופעה משותפת באותו עמוד")}</h2><p class="small muted">${T("מספר העמודים שבהם שני המושגים מופיעים יחד. הופעה משותפת אינה קשר סיבתי או קשר מתועד בין המופעים. מוצגים עד 35 מושגים פעילים; האלכסון הוא מספר העמודים עם כל מושג.")}</p><div class="tablewrap"><table><thead><tr><th></th>${active.map(c=>`<th>${esc(L(c,'label'))}</th>`).join('')}</tr></thead><tbody>${active.map(a=>`<tr><th>${esc(L(a,'label'))}</th>${active.map(b=>{const both=ims.filter(im=>matches(a.id,im.id).length&&matches(b.id,im.id).length);return `<td><button class="heat" data-action="co-drill" data-concept="${a.id}" data-other="${b.id}" style="background:rgba(121,97,155,${.08+.75*both.length/Math.max(1,ims.length)})">${both.length}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
if(ui.analysis==='network'){const imageSet=new Set(ims.map(x=>x.id));const anns=P.annotations.filter(a=>imageSet.has(a.imageId)&&(!ui.author||a.author===ui.author)&&(ui.analysisLayer==='all'||(ui.analysisLayer!=='meaning'&&a.conceptIds.some(id=>groupOf(P.concepts.find(c=>c.id===id))?.layer===ui.analysisLayer))));const claims=P.claims.filter(c=>(ui.analysisLayer==='all'||ui.analysisLayer==='meaning')&&(!ui.author||c.author===ui.author)&&c.evidence.some(id=>P.annotations.some(a=>a.id===id&&imageSet.has(a.imageId))));for(const c of claims)for(const id of c.evidence){const a=P.annotations.find(a=>a.id===id);if(a&&imageSet.has(a.imageId)&&!anns.some(x=>x.id===id))anns.push(a);}const nodes=[...anns,...claims].map(x=>({id:x.id,...nodeInfo(x.id)}));const allowed=new Set(nodes.map(n=>n.id));let edges=claims.flatMap(c=>c.evidence.filter(id=>allowed.has(id)).map(id=>({source:c.id,target:id,label:T("מבוסס על")})));for(const r of P.relations){if(![r.source,r.target].some(id=>allowed.has(id)))continue;for(const id of [r.source,r.target])if(!allowed.has(id)){const n=nodeInfo(id);if(n.type==='concept'||(n.type==='image'&&imageSet.has(id))){allowed.add(id);nodes.push({id,...n});}}if(allowed.has(r.source)&&allowed.has(r.target))edges.push({...r,label:P.relationTypes.find(t=>t.id===r.typeId)?.label});}html+=`<div class="panel"><h2>${T("רשת המופעים והטענות")}</h2><p class="small muted">${T("ירוק: סימון; סגול: טענה. הקשרים כאן נשמרו בפרויקט או מעגנים טענה בראיה. הם אינם מחושבים מהופעה משותפת. ראיות לטענות נכללות כהקשר גם אם המתייג או השכבה שלהן שונים מהמסנן. ")}${nodes.length>160?T("תצוגה מוגבלת ל־160 צמתים; צמצמו לפי יצירה או מתייג."):''}</p>${graph(nodes,edges,'evidence')}</div>`;}
if(ui.analysis==='table')html+=`<div class="panel"><h2>${T("סימונים במקור")}</h2><div class="tablewrap"><table><thead><tr><th>${T("עמוד")}</th><th>${T("תיאור")}</th><th>${T("תגיות")}</th><th>${T("מתייג/ת")}</th><th></th></tr></thead><tbody>${ann.map(a=>`<tr><td>${esc(L(P.images.find(im=>im.id===a.imageId),'title'))}</td><td>${esc(L(a,'label'))}</td><td>${a.conceptIds.map(id=>esc(conceptLabel(id))).join(', ')}</td><td>${esc(a.author)}</td><td>${btn('jump-annotation',T("פתיחת סימון"),'',`data-id="${a.id}"`)}</td></tr>`).join('')}${claims.map(c=>`<tr><td>${T("טענה · ")}${c.evidence.length} ${T("ראיות")}</td><td>${esc(L(c,'text'))}</td><td>${c.conceptIds.map(id=>esc(conceptLabel(id))).join(', ')}</td><td>${esc(c.author)}</td><td>${btn('edit-claim',T("פתיחת טענה"),'',`data-id="${c.id}"`)} ${btn('jump-annotation',T("ראיה במקור"),'',`data-id="${c.evidence[0]}"`)}</td></tr>`).join('')}</tbody></table></div></div>`;
return html;}
function drill(conceptId,imageId){const ims=analysisImages().filter(im=>!imageId||im.id===imageId);const rows=[...new Map(ims.flatMap(im=>matches(conceptId,im.id)).map(m=>[m.id,m])).values()];openDialog(`<h2>${esc(conceptLabel(conceptId))}</h2><p class="muted">${rows.length} ${T("סימונים / טענות ייחודיים בתצוגה שנבחרה.")}</p>${rows.map(m=>{const x=(m.kind==='claim'?P.claims:P.annotations).find(a=>a.id===m.id);return `<div class="${m.kind==='claim'?'claim':'annotitem'}"><b>${esc(L(x,'text')||L(x,'label')||x.conceptIds.map(conceptLabel).join(', '))}</b><p class="small">${esc(L(x,'note')||'')} · ${esc(x.author||T("ללא שם"))}</p>${m.kind==='claim'?x.evidence.map(id=>btn('jump-annotation',esc(annotationLabel(P.annotations.find(a=>a.id===id))),'',`data-id="${id}"`)).join(' '):btn('jump-annotation',T("פתיחת העמוד והסימון"),'primary',`data-id="${x.id}"`)}</div>`;}).join('')||H("<div class=\"notice\">אין מופעים במסנן הנוכחי. בדקו במפת החום אם העמוד נבדק.</div>")}`);}
function renderHelp(){const steps=[
[B('אוספים ומסדרים','Collect and order'),B('הוסיפו כמה תמונות. תנו להן כותרות ושייכו ליצירות. גררו לשינוי הסדר; מספר עמוד המקור נשמר בנפרד.','Add multiple images, title them and assign works. Drag to change sequence order; source page numbers are stored separately.')],
[B('מגדירים שפה מחקרית','Define your research vocabulary'),B('צרו קבוצה כמו צבעים או סוגי אובייקטים. בחרו שכבה, הוסיפו ערכים ותתי־סוגים, או עברו למקורות ובחרו מתוך אוצר קיים.','Create a group such as colours or object types. Choose a layer and add terms and subtypes, or browse an existing vocabulary and adopt selected terms.')],
[B('מסמנים את מה שרואים','Annotate what is visible'),B('פתחו עמוד ובחרו מלבן, נקודה או מצולע. אחרי הסימון הוסיפו תיאור ותגיות. לסיום מצולע: לחיצה כפולה או Enter. Escape מבטל סימון שטרם נשמר.','Open a page and choose rectangle, point or polygon. Add a description and tags after drawing. Finish a polygon with double-click or Enter. Escape cancels an unfinished drawing.')],
[B('מוסיפים טענה וראיות','Add a claim and its evidence'),B('לחצו על טענה פרשנית, כתבו מה אתם טוענים ובחרו סימון אחד או כמה כראיות. ציינו הסבר ומידת ודאות. אותה ראיה יכולה לתמוך בכמה טענות.','Create an interpretation claim, state your reading and select one or more annotations as evidence. Add an explanation and confidence. The same evidence may support multiple claims.')],
[B('מחברים ובודקים','Connect and review'),B('קשר נוצר בבחירת מקור, יחס ויעד. סדר קריאה שונה מזמן הסיפור. בסיום בדיקת כל עמוד סמנו אילו קבוצות בדקתם.','Create a link by choosing a source, relation and target. Reading order differs from story time. Mark which groups you reviewed on each page.')],
[B('קוראים מרחוק וחוזרים לעמוד','Read at a distance and return to the page'),B('פתחו מפת חום, שכיחויות, הופעה משותפת או רשת ראיות. לחצו על תא או עמודה כדי לפתוח את הסימונים שהפיקו את הנתון.','Open the heatmap, frequencies, co-occurrence or evidence network. Click a cell or bar to open the annotations behind the result.')],
[B('שומרים ומעבירים','Save and transfer'),B('הורדת פרויקט יוצרת ZIP עם התמונות, המודל, התרגומים והתיוגים. שמירת הדפדפן מקומית בלבד. לשיעור משותף חלקו חבילת בסיס אחת, ואחדו אחר כך את העותקים של התלמידים.','Download a project ZIP containing images, model, translations and annotations. Browser autosave is local only. For classroom aggregation, distribute one baseline project and later merge students’ copies.')]
];return `<div class="reading">${heading(B('מדריך עבודה','Working guide'),B('מה עושים, ובאיזה סדר?','What to do, and in what order?'),B('מסלול קצר לעבודה עצמאית ולתרגול בכיתה. כפתורי ⓘ ברחבי המערכת פותחים הסבר ממוקד בלי לסגור טופס פתוח.','A practical path for independent work and classroom exercises. Information buttons open focused help without discarding an open form.'))}<div class="onboarding"><h2>${B('נסו קודם את הדוגמה','Try the example first')}</h2><p>${B('ארבע תמונות סכמטיות, תיוגים וטענות מוכנים מדגימים את כל המסלול. אלו איורי הוראה, לא מקורות היסטוריים.','Four schematic images with prepared annotations and claims demonstrate the workflow. These are teaching illustrations, not historical sources.')}</p>${btn('demo',B('פתיחת דוגמה לימודית','Open teaching example'),'primary')}</div><div class="panel">${steps.map(([title,body],i)=>`<div class="help-step"><span class="step">${i+1}</span><div><h3>${title}</h3><p>${body}</p></div></div>`).join('')}</div>
<div class="panel"><h2>${B('תיאור, מושג ומשמעות','Description, concept and meaning')}</h2><table><thead><tr><th>${B('סוג הנתון','Data type')}</th><th>${B('דוגמה','Example')}</th></tr></thead><tbody><tr><td>${B('מושג באוצר המילים','Vocabulary concept')}</td><td>${B('גדר תיל היא סוג של גדר.','A barbed-wire fence is a kind of fence.')}</td></tr><tr><td>${B('מופע מסומן','Annotated occurrence')}</td><td>${B('הגדר המסוימת בפאנל השני בעמוד 4.','The particular fence in panel two on page 4.')}</td></tr><tr><td>${B('טענה פרשנית','Interpretive claim')}</td><td>${B('הגדר מדגישה חוויה של כליאה; הטענה מקושרת לראיות.','The fence emphasises confinement; this claim is linked to its evidence.')}</td></tr></tbody></table><p>${B('גם תיאור הוא החלטה של חוקר. ההפרדה מבהירה מה נטען ובאיזה בסיס, ומאפשרת לשמור מחלוקות.','Description also involves scholarly judgment. The separation clarifies what is claimed and on what basis, while retaining disagreements.')}</p></div>
<div class="panel"><h2>${B('דו־לשוניות בלי אובדן מידע','Bilingual data without information loss')}</h2><p>${B('שפת הממשק נבחרת למעלה. בתוך טפסי הנתונים יש שדות נפרדים לעברית ולאנגלית. אפשר למלא שפה אחת או שתיים; שפה חסרה אינה מתורגמת אוטומטית. המתג עברית + English מציג את שתי התוויות יחד. נתוני מקור בשפות נוספות נשמרים בייבוא ובייצוא.','Choose the interface language in the header. Data forms provide separate Hebrew and English fields. Fill either or both; missing translations are not invented. The Hebrew + English switch displays both labels. Additional source languages are retained on import and export.')}</p></div>
<div class="panel"><h2>${B('איך מייבאים אונטולוגיה?','How do I import an ontology?')}</h2><ol><li>${B('עברו אל מושגים וקשרים ← מקורות וערכות. בחרו ערכה מוכנה, קובץ מקומי או חיבור לכתובת RDF.','Go to Concepts and relations → Sources and packs. Choose a bundled pack, a local file or an RDF URL.')}</li><li>${B('בדקו את דוח הייבוא. חפשו מונחים בעברית, באנגלית או לפי מזהה; צפו בהגדרות וברשת.','Inspect the import report. Search Hebrew, English or identifiers, then inspect definitions and the network.')}</li><li>${B('סמנו ערכים. מומלץ להשאיר את האפשרות לכלול מושגי אב, כדי לשמור את ההיררכיה. בחרו את שכבת הנתונים ואמצו לפרויקט.','Select terms. Keep “include broader concepts” enabled to preserve the hierarchy. Choose the data layer and adopt them into the project.')}</li></ol><p>${B('נתמכים JSON, JSON-LD עם הקשרים מקומיים, RDF/XML, Turtle, N-Triples, CSV ו־SPARQL JSON של שלשות s/p/o. הייבוא שומר שפות, מונחים חלופיים, היררכיה וקשרים נתמכים. הוא אינו מריץ הסקת OWL או טוען אוטומטית אונטולוגיות מיובאות.','Supported inputs include JSON, JSON-LD with local contexts, RDF/XML, Turtle, N-Triples, CSV and SPARQL JSON with s/p/o triples. Languages, alternative labels, hierarchy and supported relationships are retained. The importer does not run OWL reasoning or automatically load imported ontologies.')}</p><p>${B('טעינה מקוונת תלויה בהרשאות CORS של אתר המקור. אם היא נחסמת, הורידו את קובץ הנתונים מהמקור וייבאו אותו מקומית. כישלון בחיבור אינו מוחק נתונים.','Online loading depends on the source server’s CORS permissions. If blocked, download its data file and import it locally. A failed connection never deletes existing data.')}</p></div>
<div class="panel"><h2>${B('איך מפרשים את הגרפים?','How should I read the charts?')}</h2><p>${B('במפת חום, 0 מציין שהקבוצה נבדקה ולא נמצא מופע; — מציין שטרם הוצהר על בדיקה. כוכבית ליד מספר אומרת שנמצאו מופעים אך הבדיקה טרם הושלמה. מצב הבדיקה משותף לפרויקט, ולא נפרד לכל מתייג.','In a heatmap, 0 means the group was reviewed and no match found; — means review has not been declared. An asterisk means matches exist but review is incomplete. Review status is shared by the project, not tracked separately per annotator.')}</p><p>${B('שכיחות של סימונים, מספר עמודים ומספר יצירות הם מדדים שונים. טענה הנתמכת בכמה עמודים נספרת פעם אחת במדד הטענות הכולל. הופעה משותפת אינה קשר סיבתי או יחס שנרשם.','Annotation counts, page counts and work counts measure different things. A claim spanning several pages is counted once in the overall claim count. Co-occurrence is neither causality nor an explicitly recorded relation.')}</p></div>
<div class="panel"><h2>${B('שמירה, איחוד וגבולות','Saving, merging and limits')}</h2><p>${B('הפרויקט הפעיל נשמר ב־IndexedDB של הדפדפן. הורידו ZIP כגיבוי נייד. באיחוד, עמודים עם אותו מזהה ואותם בתי תמונה מאוחדים; סימונים וטענות שנערכו אחרת נשמרים כגרסאות נפרדות. אין שיתוף בזמן אמת. ביטול פעולה זמין עד 18 פעולות בהפעלה הנוכחית.','The active project is stored in the browser’s IndexedDB. Download a ZIP as a portable backup. Merging unifies pages with matching IDs and image bytes; conflicting annotations and claims are kept as separate versions. There is no real-time collaboration. Undo covers up to 18 actions in the current session.')}</p><p>${B('התמונות נשמרות במחשב ובחבילת הפרויקט. רק בקשה מפורשת לטעינת אונטולוגיה יוצרת בקשת רשת; התמונות אינן מצורפות אליה. אין OCR או הסקה אוטומטית. התאימו את נפח התמונות לזיכרון המחשב.','Images remain on your computer and in the project package. Only an explicit ontology-loading action creates a network request; images are never attached to it. There is no OCR or automatic reasoning. Keep image sizes appropriate for device memory.')}</p></div><div class="panel"><h2>${B('מקורות וייחוס','Sources and attribution')}</h2>${MabatPacks.filter(p=>safeURL(p.source)).map(p=>`<p>${link(p.source,L(p,'name')||L(p))}<br><small>${esc(p.license||'')}</small></p>`).join('')}<p>${B('התרגומים לעברית בערכות החיצוניות הם מקומיים. ערכת קומיקס שואה היא הצעה לדיון בכיתה ואינה תזאורוס מוסמך או נתוני EHRI.','Hebrew labels in external packs are local translations. The Holocaust-comics teaching pack is a local discussion proposal, not an authoritative thesaurus or EHRI data.')}</p></div></div>`;}
function drawOverlay(){const svg=$('overlay'),im=getImage();if(!svg||!im)return;const w=im.width,h=im.height;const shapes=P.annotations.filter(a=>a.imageId===im.id).map((a,i)=>{const g=a.geometry,color=groupOf(P.concepts.find(c=>c.id===a.conceptIds[0]))?.color||'#1d6658';let shape='';const attr=`class="region ${a.id===ui.selected?'selected':''}" data-ann="${a.id}" stroke="${color}" fill="${color}"`;if(g.type==='rect'){const [[x,y],[x2,y2]]=g.points;shape=`<rect ${attr} x="${x*w}" y="${y*h}" width="${(x2-x)*w}" height="${(y2-y)*h}"/>`;}if(g.type==='point'){const [[x,y]]=g.points;shape=`<circle ${attr} cx="${x*w}" cy="${y*h}" r="${w/80}"/>`;}if(g.type==='polygon')shape=`<polygon ${attr} points="${g.points.map(([x,y])=>`${x*w},${y*h}`).join(' ')}"/>`;if(g.type==='page')shape=`<rect ${attr} x="${w*.005}" y="${h*.005}" width="${w*.99}" height="${h*.99}" stroke-dasharray="${w/50}"/>`;const [x,y]=g.points?.[0]||[.02,.02];return shape+`<text x="${x*w+w/100}" y="${y*h+w/28}" style="font-size:${w/40}px;stroke-width:${w/150}px">${i+1}</text>`;}).join('');let preview='';if(draft?.geometry){const g=draft.geometry;const p=g.points;if(g.type==='rect')preview=`<rect x="${Math.min(p[0][0],p[1][0])*w}" y="${Math.min(p[0][1],p[1][1])*h}" width="${Math.abs(p[1][0]-p[0][0])*w}" height="${Math.abs(p[1][1]-p[0][1])*h}" fill="#b68a4230" stroke="#b68a42" stroke-width="${w/250}"/>`;if(g.type==='move'){const points=p.map(([x,y])=>`${x*w},${y*h}`).join(' ');preview=`<polyline points="${points}" fill="none" stroke="#b68a42" stroke-width="${w/200}"/>`;}}
if(polygon.length)preview+=`<polyline points="${polygon.map(([x,y])=>`${x*w},${y*h}`).join(' ')}" fill="#b68a4220" stroke="#b68a42" stroke-width="${w/250}"/>`+polygon.map(([x,y])=>`<circle cx="${x*w}" cy="${y*h}" r="${w/180}" fill="#b68a42"/>`).join('');svg.innerHTML=shapes+preview;}
function bindCanvas(){const svg=$('overlay');if(!svg)return;drawOverlay();const pos=e=>{const r=svg.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];};svg.onpointerdown=e=>{if(e.button!==0)return;const p=pos(e),ann=e.target.closest('[data-ann]')?.dataset.ann;if(ui.tool==='select'){if(ann){ui.selected=ann;render();}return;}if(ui.tool==='point'){annotationForm(null,{type:'point',points:[p]});return;}if(ui.tool==='polygon'){polygon.push(p);drawOverlay();return;}if(ui.tool==='move'){const a=P.annotations.find(a=>a.id===ann);if(!a||a.geometry.type==='page')return;draft={id:ann,start:p,original:C.clone(a.geometry),geometry:{type:'move',points:C.clone(a.geometry.points)}};}else draft={start:p,geometry:{type:'rect',points:[p,p]}};svg.setPointerCapture(e.pointerId);};svg.onpointermove=e=>{if(!draft)return;const p=pos(e);if(draft.id){const pts=draft.original.points,dx=Math.max(-Math.min(...pts.map(p=>p[0])),Math.min(1-Math.max(...pts.map(p=>p[0])),p[0]-draft.start[0])),dy=Math.max(-Math.min(...pts.map(p=>p[1])),Math.min(1-Math.max(...pts.map(p=>p[1])),p[1]-draft.start[1]));draft.geometry.points=pts.map(([x,y])=>[x+dx,y+dy]);}else draft.geometry.points[1]=p;drawOverlay();};svg.onpointerup=e=>{if(!draft)return;const d=draft;draft=null;if(d.id){mutate(T("הזזת סימון"),()=>{const a=P.annotations.find(a=>a.id===d.id);a.geometry.points=d.geometry.points;a.updated=C.now();ui.selected=a.id;});}else{const [a,b]=d.geometry.points;if(Math.abs(a[0]-b[0])<.004||Math.abs(a[1]-b[1])<.004){drawOverlay();return;}const g={type:'rect',points:[[Math.min(a[0],b[0]),Math.min(a[1],b[1])],[Math.max(a[0],b[0]),Math.max(a[1],b[1])]]};drawOverlay();const redraw=ui.redraw;ui.redraw=null;annotationForm(redraw,g);}};svg.onpointercancel=()=>{draft=null;drawOverlay();};svg.ondblclick=e=>{if(ui.tool==='polygon'){e.preventDefault();finishPolygon();}};}
function finishPolygon(){if(polygon.length<3){toast(T("למצולע דרושים שלושה קודקודים לפחות."));return;}let points=polygon.filter((p,i,a)=>!i||Math.hypot(p[0]-a[i-1][0],p[1]-a[i-1][1])>.001);if(points.length<3)return;polygon=[];drawOverlay();annotationForm(null,{type:'polygon',points});}
async function addImages(files){const read=f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(f);});const loaded=[];for(const file of [...files].sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}))){if(!/^image\/(png|jpeg|webp|gif|bmp|avif)$/.test(file.type)){toast('דולג קובץ שאינו תמונה נתמכת: '+file.name);continue;}const data=await read(file);const dims=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve([im.naturalWidth,im.naturalHeight]);im.onerror=()=>reject(Error('לא ניתן לקרוא: '+file.name));im.src=data;});loaded.push({im:{id:C.uid(),name:file.name,title:file.name.replace(/\.[^.]+$/,''),work:'',page:'',width:dims[0],height:dims[1],mime:file.type,checkedGroups:[]},data});}
if(loaded.length)mutate('הוספת '+loaded.length+' תמונות',()=>loaded.forEach(({im,data})=>{P.images.push(im);assets[im.id]=data;}));toast('נוספו '+loaded.length+' תמונות.');}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);}
function slug(){return (P.name||'mabat-project').replace(/[^\p{L}\p{N}_-]/gu,'_').slice(0,70);}
async function exportProject(){try{const errors=C.validate(P,assets);if(errors.length)throw Error(errors.join('; '));const zip=new JSZip(),out=C.clone(P);for(const im of out.images){const mime=assets[im.id].slice(5,assets[im.id].indexOf(';'));const ext=({'image/jpeg':'jpg','image/svg+xml':'svg'})[mime]||mime.split('/')[1];im.assetPath='images/'+im.id+'.'+ext;zip.file(im.assetPath,assets[im.id].split(',')[1],{base64:true});}zip.file('project.json',JSON.stringify(out,null,2));zip.file('README.txt','Mabat project package v1. Open in Mabat using Open / Merge. Includes source images, vocabulary, annotations, claims, relations and history.\n');downloadBlob(await zip.generateAsync({type:'blob',compression:'DEFLATE'}),slug()+'.mabat.zip');toast(T("חבילת הפרויקט הוכנה להורדה."));}catch(e){toast('הייצוא נכשל: '+e.message);}}
async function readProject(file){let p,a={};if(/\.zip$/i.test(file.name)){const z=await JSZip.loadAsync(file),pj=z.file('project.json');if(!pj)throw Error(T("בחבילה חסר project.json. זה אינו ZIP של פרויקט מבט."));p=JSON.parse(await pj.async('string'));if(!Array.isArray(p.images))throw Error(T("מבנה הפרויקט אינו תקין"));for(const im of p.images){if(!im.assetPath||!/^images\/[A-Za-z0-9_.-]+$/.test(im.assetPath))throw Error(T("נתיב תמונה לא נתמך"));const f=z.file(im.assetPath);if(!f)throw Error('תמונה חסרה: '+im.name);const base64=await f.async('base64');const ext=im.assetPath.split('.').pop(),mime=({'jpg':'image/jpeg','svg':'image/svg+xml'})[ext]||'image/'+ext;a[im.id]='data:'+mime+';base64,'+base64;delete im.assetPath;}}else{const raw=JSON.parse(await file.text());p=raw.project||raw;a=raw.assets||{};}
const errors=C.validate(p,a);if(errors.length)throw Error(errors.join('\n'));return {p,a};}
async function loadProject(file){try{const {p,a}=await readProject(file);if(importMode==='merge'){const merged=C.merge(P,p,assets,a);checkpoint('איחוד פרויקט '+p.name);P=merged.project;assets=merged.assets;P.updated=C.now();P.history.push({id:C.uid(),time:C.now(),author:P.author,action:`${T("איחוד ")}${p.name}: ${merged.added} ${T("רשומות; ")}${merged.forked} ${T("מזהים פוצלו; ")}${merged.metadataConflicts} ${T("שדות עמוד סותרים נשמרו לפי הראשי")}`});toast(`${T("נוספו ")}${merged.added} ${T("רשומות. ")}${merged.forked} ${T("מזהים עם שינויים נשמרו בנפרד.")}${merged.metadataConflicts?` ${merged.metadataConflicts} ${T("שדות עמוד סותרים נשארו לפי הפרויקט הראשי.")}`:''}`);}else{checkpoint(T("פתיחת פרויקט"));P=p;assets=a;toast(T("הפרויקט נטען."));}ui.imageId=null;ui.selected=null;ui.work='';ui.author='';scheduleSave();render();}catch(e){toast('לא ניתן לטעון את הפרויקט: '+e.message);}}
function exportTables(){const zip=new JSZip();const images=P.images.map((im,i)=>({image_id:im.id,sequence:i+1,source_page:im.page,title:im.title,work:im.work,filename:im.name,title_he:F(im,'title','he'),title_en:F(im,'title','en'),work_he:F(im,'work','he'),work_en:F(im,'work','en'),checked_groups:im.checkedGroups}));const annotations=P.annotations.map(a=>({annotation_id:a.id,image_id:a.imageId,sequence:P.images.findIndex(im=>im.id===a.imageId)+1,label:a.label,label_he:F(a,'label','he'),label_en:F(a,'label','en'),note_he:F(a,'note','he'),note_en:F(a,'note','en'),concept_ids:a.conceptIds,concept_labels:a.conceptIds.map(conceptLabel),geometry:a.geometry,author:a.author,note:a.note,created:a.created,updated:a.updated}));const claims=P.claims.map(c=>({...c,text_he:F(c,'text','he'),text_en:F(c,'text','en'),note_he:F(c,'note','he'),note_en:F(c,'note','en'),concept_labels:c.conceptIds.map(conceptLabel)}));const relations=P.relations.map(r=>({...r,note_he:F(r,'note','he'),note_en:F(r,'note','en'),type_label:P.relationTypes.find(t=>t.id===r.typeId)?.label,source_label:nodeInfo(r.source).label,target_label:nodeInfo(r.target).label}));const concepts=P.concepts.map(c=>({...c,group:groupOf(c)?.label,layer:groupOf(c)?.layer}));for(const [name,rows] of Object.entries({images,annotations,claims,relations,concepts,relation_types:P.relationTypes,concept_links:P.conceptLinks}))zip.file(name+'.csv',C.csv(rows));
const ims=analysisImages(),cons=analysisConcepts();const counts=cons.flatMap(c=>ims.map(im=>({concept_id:c.id,concept:c.label,concept_he:F(c,'label','he'),concept_en:F(c,'label','en'),image_id:im.id,sequence:P.images.indexOf(im)+1,source_page:im.page,work:im.work,count:matches(c.id,im.id).length,group_checked:im.checkedGroups.includes(c.groupId),include_descendants:ui.descendants,author_filter:ui.author})));zip.file('filtered_counts.csv',C.csv(counts));zip.file('project-without-images.json',JSON.stringify(P,null,2));zip.file('README.txt','Tables use UTF-8 BOM and CSV quoting. Arrays/geometry are JSON in cells. Formula-like text is prefixed with apostrophe for spreadsheet safety.\nfiltered_counts.csv respects current work/layer/author/descendant filters, counts occurrences per page.\nproject-without-images.json is an analysis snapshot; use the full Mabat ZIP to reopen/edit with images.\n');return zip.generateAsync({type:'blob',compression:'DEFLATE'}).then(blob=>downloadBlob(blob,slug()+'.data.zip'));}
function demo(){if(P.images.length||P.annotations.length){openDialog(`<h2>${T("פתיחת דוגמה לימודית")}</h2><p>${T("הדוגמה תחליף את הפרויקט הפעיל. אפשר להוריד את העבודה הנוכחית לפני ההחלפה; ניתן גם לבטל את הפעולה באותה הפעלה.")}</p><div class="toolbar">${btn('export-project',T("הורדת העבודה הנוכחית"))}${btn('confirm-demo',T("פתיחת הדוגמה"),'primary')}</div>`);return;}buildDemo();}
function buildDemo(){checkpoint(T("טעינת דוגמה לימודית"));P=C.fresh();P.name=T("דוגמה לימודית · מן העמוד לדפוס");P.author=T("דוגמה");assets={};C.importTerms(P,MabatPacks[0],MabatPacks[0].terms.map(t=>t.id));C.importTerms(P,MabatPacks[4],MabatPacks[4].terms.map(t=>t.id));const person=P.concepts.find(c=>c.label==='אדם'),wire=P.concepts.find(c=>c.label==='גדר תיל'),train=P.concepts.find(c=>c.label==='רכבת'),meaning=P.concepts.find(c=>c.label==='כליאה');for(let i=0;i<4;i++){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="760" height="960" viewBox="0 0 760 960"><rect width="760" height="960" fill="#faf6eb"/><text x="380" y="60" text-anchor="middle" font-size="26" fill="#183e38" font-family="Calibri, sans-serif">TEACHING EXAMPLE · ${i+1}</text><rect x="45" y="95" width="670" height="360" fill="#dce5df" stroke="#183e38" stroke-width="5"/><rect x="45" y="490" width="670" height="360" fill="#e4dfd5" stroke="#183e38" stroke-width="5"/><circle cx="230" cy="225" r="38" fill="#183e38"/><path d="M230 263 L230 365 M230 280 L170 325 M230 280 L290 325 M230 365 L185 420 M230 365 L275 420" stroke="#183e38" stroke-width="15" fill="none"/>${i!==2?'<path d="M440 140 V430 M490 140 V430 M540 140 V430 M590 140 V430 M410 190 H650 M410 250 H650 M410 310 H650 M410 370 H650" stroke="#5f6d66" stroke-width="5"/>':''}${i>0?'<rect x="180" y="610" width="390" height="130" rx="10" fill="#75877c"/><rect x="210" y="630" width="65" height="45" fill="#faf6eb"/><rect x="300" y="630" width="65" height="45" fill="#faf6eb"/><rect x="390" y="630" width="65" height="45" fill="#faf6eb"/><circle cx="250" cy="750" r="26" fill="#183e38"/><circle cx="490" cy="750" r="26" fill="#183e38"/>':''}<text x="380" y="910" text-anchor="middle" font-size="18" fill="#64746c" font-family="Calibri, sans-serif">Schematic illustration — not a historical source</text></svg>`;const id=C.uid();assets[id]='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(svg)));P.images.push({id,name:'teaching-page-'+(i+1)+'.svg',title:'עמוד דוגמה '+(i+1),work:T("אוסף הדגמה"),page:String(i+1),width:760,height:960,mime:'image/svg+xml',checkedGroups:i===3?[]:P.groups.map(g=>g.id)});const a={id:C.uid(),imageId:id,label:T("אדם"),conceptIds:[person.id],geometry:{type:'rect',points:[[.21,.18],[.4,.45]]},author:T("דוגמה"),created:C.now(),updated:C.now(),note:T("סימון הדגמה")};P.annotations.push(a);if(i!==2){const b={id:C.uid(),imageId:id,label:T("גדר תיל"),conceptIds:[wire.id],geometry:{type:'rect',points:[[.53,.14],[.87,.45]]},author:T("דוגמה"),created:C.now(),updated:C.now(),note:T("סימון הדגמה")};P.annotations.push(b);P.claims.push({id:C.uid(),text:T("הגדר עשויה להדגיש כליאה"),conceptIds:[meaning.id],evidence:[a.id,b.id],note:T("פרשנות לדוגמה בלבד; אינה טענה על חומר היסטורי."),confidence:'מוצע לדיון',author:T("דוגמה"),created:C.now(),updated:C.now()});P.relations.push({id:C.uid(),source:a.id,target:b.id,typeId:P.relationTypes.find(r=>r.label==='משמאל בדף').id,note:T("מיקום חזותי בדימוי הסכמטי"),author:T("דוגמה"),created:C.now()});}if(i>0)P.annotations.push({id:C.uid(),imageId:id,label:T("רכבת"),conceptIds:[train.id],geometry:{type:'rect',points:[[.22,.62],[.77,.82]]},author:T("דוגמה"),created:C.now(),updated:C.now(),note:''});}P.history.push({id:C.uid(),time:C.now(),author:T("מבט"),action:T("יצירת דוגמה סכמטית")});ui.imageId=P.images[0].id;ui.selected=null;ui.tab='collection';closeDialog();scheduleSave();render();toast(T("הדוגמה נטענה. התמונות סכמטיות ונוצרו להדרכה."));}
function deleteAnnotation(id){const claims=P.claims.filter(c=>c.evidence.includes(id)),orphans=claims.filter(c=>c.evidence.length===1).map(c=>c.id);askDelete('מחיקת הסימון תסיר את הקשרים המחוברים אליו. '+(claims.length?`${claims.length} ${T("טענות משתמשות בו; ")}${orphans.length} ${T("מהן יימחקו כי יישארו ללא ראיה.")}`:''),()=>{const removed=new Set([id,...orphans]);P.annotations=P.annotations.filter(a=>a.id!==id);P.claims=P.claims.filter(c=>!orphans.includes(c.id));P.claims.forEach(c=>c.evidence=c.evidence.filter(x=>x!==id));P.relations=P.relations.filter(r=>!removed.has(r.source)&&!removed.has(r.target));ui.selected=null;});}
